svg.script:
window.KRIMELH = {
  setColor(letter, color) {
    const key = String(letter).toLowerCase();
    if (!'krimelh'.includes(key)) return;
    document.documentElement.style.setProperty('--edge-' + key, color);
  },
  setAllColors(color) {
    for (const key of 'krimelh') {
      document.documentElement.style.setProperty('--edge-' + key, color);
    }
  },
  setFlicker(letter, seconds) {
    const el = document.getElementById('letter-' + String(letter).toLowerCase());
    if (el) el.style.setProperty('--flicker-speed', seconds + 's');
  }
};
